python
def firstArrivalsPeakTicket(readings, k):
    a=readings
    out=[]
    seen=set()
    for x in a:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return max(out,default=0)


java
class Solution {
  public int firstArrivalsPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>seen=new HashSet<>();for(int x:a)if(seen.add(x))out.add(x);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
